#!/bin/sh
# Drawplate installer source. The distribution is generated by build-installers.ps1.

set -eu

VERSION="${DRAWPLATE_VERSION:-}"
INSTALL_DIR="${DRAWPLATE_INSTALL_DIR:-}"
REPO="${DRAWPLATE_REPO:-migueljocode/Drawplate}"
BASE_URL="${DRAWPLATE_BASE_URL:-https://github.com/$REPO/releases}"
FROM_ARCHIVE="${DRAWPLATE_FROM_ARCHIVE:-}"
FROM_SHA256="${DRAWPLATE_SHA256:-}"
NO_SETUP="${DRAWPLATE_NO_SETUP:-0}"
YES="${DRAWPLATE_YES:-0}"
UNINSTALL="${DRAWPLATE_UNINSTALL:-0}"

LOCK_DIR=""
STAGING_DIR=""
CURL_PID=""

# ---------------------------------------------------------------------------
# Terminal capabilities. Redirected output stays plain ASCII (T-INS-08).
# ---------------------------------------------------------------------------
USE_UI=0
USE_ERR_UI=0
UTF8=0
TRUECOLOR=0
ESC=""
CR=""
if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ "${TERM:-}" != "dumb" ]; then
    USE_UI=1
fi
if [ -t 2 ] && [ -z "${NO_COLOR:-}" ] && [ "${TERM:-}" != "dumb" ]; then
    USE_ERR_UI=1
fi
if [ "$USE_UI" -eq 1 ] || [ "$USE_ERR_UI" -eq 1 ]; then
    ESC=$(printf '\033')
    CR=$(printf '\r')
    case "${COLORTERM:-}" in truecolor|24bit) TRUECOLOR=1 ;; esac
    case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
        *[Uu][Tt][Ff]-8*|*[Uu][Tt][Ff]8*) UTF8=1 ;;
    esac
fi

# Palette: truecolor when available, otherwise the 16 basic colors.
C_RESET="" C_OK="" C_INFO="" C_ACCENT="" C_TEXT="" C_SOFT="" C_MUTED="" C_ERR="" C_WARN="" C_G1="" C_G4="" C_BOLD=""
if [ -n "$ESC" ]; then
    C_RESET="${ESC}[0m"
    C_BOLD="${ESC}[1m"
    if [ "$TRUECOLOR" -eq 1 ]; then
        C_OK="${ESC}[38;2;52;211;153m"
        C_INFO="${ESC}[38;2;56;189;248m"
        C_ACCENT="${ESC}[38;2;34;211;238m"
        C_TEXT="${ESC}[38;2;241;245;249m"
        C_SOFT="${ESC}[38;2;148;163;184m"
        C_MUTED="${ESC}[38;2;100;116;139m"
        C_ERR="${ESC}[38;2;248;113;113m"
        C_WARN="${ESC}[38;2;251;191;36m"
        C_G1="${ESC}[38;2;16;185;129m"
        C_G4="${ESC}[38;2;139;92;246m"
    else
        C_OK="${ESC}[32m"
        C_INFO="${ESC}[34m"
        C_ACCENT="${ESC}[36m"
        C_TEXT="${ESC}[97m"
        C_SOFT="${ESC}[37m"
        C_MUTED="${ESC}[90m"
        C_ERR="${ESC}[31m"
        C_WARN="${ESC}[33m"
        C_G1="${ESC}[32m"
        C_G4="${ESC}[35m"
    fi
fi

# Glyphs are written as octal escapes so this file stays ASCII-only.
if [ "$UTF8" -eq 1 ]; then
    G_FULL=$(printf '\342\226\210')
    G_H=$(printf '\342\224\200')
    G_V=$(printf '\342\224\202')
    G_TL=$(printf '\342\225\255')
    G_TR=$(printf '\342\225\256')
    G_BL=$(printf '\342\225\260')
    G_BR=$(printf '\342\225\257')
    G_BAR=$(printf '\342\224\201')
    G_OK=$(printf '\342\234\223')
    G_SKIP=$(printf '\342\227\213')
    G_ERR=$(printf '\342\234\227')
    G_WARN=$(printf '\342\226\262')
    G_DOT=$(printf '\302\267')
else
    G_FULL='#' G_H='-' G_V='|' G_TL='+' G_TR='+' G_BL='+' G_BR='+'
    G_BAR='=' G_OK='+' G_SKIP='o' G_ERR='x' G_WARN='!' G_DOT='|'
fi
export G_FULL G_H G_TL G_TR G_BL G_BR G_BAR
DP_ESC=$ESC
DP_TC=$TRUECOLOR
export DP_ESC DP_TC

LABEL_W=26

# Shared awk helpers. Text always reaches awk through ENVIRON, never through
# awk -v, because -v expands backslash escapes and corrupted the banner art.
AWK_LIB='
function lerp(a, b, u) { return a + (b - a) * u }
function grad(t,   u) {
    if (t < 0) t = 0
    if (t > 1) t = 1
    if (t < 1 / 3) { u = t * 3; R = lerp(16, 6, u); G = lerp(185, 182, u); B = lerp(129, 212, u) }
    else if (t < 2 / 3) { u = (t - 1 / 3) * 3; R = lerp(6, 59, u); G = lerp(182, 130, u); B = lerp(212, 246, u) }
    else { u = (t - 2 / 3) * 3; R = lerp(59, 139, u); G = lerp(130, 92, u); B = lerp(246, 246, u) }
}
function fg(r, g, b) {
    if (ENVIRON["DP_TC"] == "1") return sprintf("%s[38;2;%d;%d;%dm", ENVIRON["DP_ESC"], r, g, b)
    return sprintf("%s[38;5;%dm", ENVIRON["DP_ESC"], 16 + 36 * int(r / 51 + 0.5) + 6 * int(g / 51 + 0.5) + int(b / 51 + 0.5))
}
'

# Paints ASCII art with a diagonal green -> cyan -> blue -> violet gradient.
# $1 art, $2 row index, $3 art width. Art symbols map to glyphs.
ui_gradient() {
    if [ "$USE_UI" -ne 1 ]; then
        printf '%s\n' "$1"
        return
    fi
    DP_TEXT=$1 DP_ROW=${2:-0} DP_W=${3:-60} awk "$AWK_LIB"'
    BEGIN {
        s = ENVIRON["DP_TEXT"]; row = ENVIRON["DP_ROW"] + 0; w = ENVIRON["DP_W"] + 0
        map["#"] = ENVIRON["G_FULL"]; map["-"] = ENVIRON["G_H"]
        map["<"] = ENVIRON["G_TL"]; map[">"] = ENVIRON["G_TR"]
        map["{"] = ENVIRON["G_BL"]; map["}"] = ENVIRON["G_BR"]
        n = length(s)
        for (i = 1; i <= n; i++) {
            ch = substr(s, i, 1)
            if (ch == " ") { printf " "; continue }
            grad((i - 1 + row * 3) / (w + 14))
            printf "%s", fg(int(R), int(G), int(B))
            printf "%s", (ch in map) ? map[ch] : ch
        }
        printf "%s[0m\n", ENVIRON["DP_ESC"]
    }' 2>/dev/null
}

ui_repeat() {
    rep_out=""
    rep_n=$2
    while [ "$rep_n" -gt 0 ]; do
        rep_out="$rep_out$1"
        rep_n=$((rep_n - 1))
    done
    printf '%s' "$rep_out"
}

ui_spinner_frame() {
    if [ "$UTF8" -eq 1 ]; then
        case $(($1 % 10)) in
            0) printf '\342\240\213' ;;
            1) printf '\342\240\231' ;;
            2) printf '\342\240\271' ;;
            3) printf '\342\240\270' ;;
            4) printf '\342\240\274' ;;
            5) printf '\342\240\264' ;;
            6) printf '\342\240\246' ;;
            7) printf '\342\240\247' ;;
            8) printf '\342\240\207' ;;
            *) printf '\342\240\217' ;;
        esac
    else
        case $(($1 % 4)) in
            0) printf '|' ;;
            1) printf '/' ;;
            2) printf '%s' '-' ;;
            *) printf '%s' '\' ;;
        esac
    fi
}

# Normalises a step label ("Finding release ........") to a fixed-width
# column so every step lines up. Sets LBL and LEADER.
ui_label() {
    LBL=$1
    while :; do
        case "$LBL" in
            *" "|*.) LBL=${LBL%?} ;;
            *) break ;;
        esac
    done
    LEADER=$(ui_repeat . $((LABEL_W - ${#LBL} - 1)))
}

ui_banner() {
    ver=$1
    if [ "$USE_UI" -ne 1 ]; then
        printf 'Drawplate installer %s\n' "$ver"
        return
    fi
    printf '\n'
    row=0
    while IFS= read -r art; do
        printf '  '
        ui_gradient "$art" "$row" 53
        row=$((row + 1))
        sleep 0.04 2>/dev/null || true
    done <<'ART'
####  ####   ###  #   # ####  #      ###  ##### #####
#   # #   # #   # #   # #   # #     #   #   #   #
#   # ####  ##### # # # ####  #     #####   #   ####
#   # #  #  #   # ## ## #     #     #   #   #   #
####  #   # #   # #   # #     ##### #   #   #   #####
ART
    printf '  '
    ui_gradient "$(ui_repeat - 53)" 5 53
    printf '  %sDrawplate installer%s %s%s%s\n\n' "$C_SOFT" "$C_RESET" "$C_ACCENT" "$ver" "$C_RESET"
}

ui_step() {
    step_tag=$1
    label=$2
    badge=$3
    detail=$4
    if [ "$USE_UI" -ne 1 ]; then
        if [ -n "$detail" ]; then
            printf '%s %s %s %s\n' "$step_tag" "$label" "$badge" "$detail"
        elif [ -n "$badge" ]; then
            printf '%s %s %s\n' "$step_tag" "$label" "$badge"
        else
            printf '%s %s\n' "$step_tag" "$label"
        fi
        return
    fi
    ui_label "$label"
    tag=${step_tag#?}
    tag=${tag%?}
    case "$badge" in
        "[ok]") glyph=$G_OK; glyph_color=$C_OK; label_color=$C_TEXT; detail_color=$C_SOFT ;;
        "[skipped]") glyph=$G_SKIP; glyph_color=$C_MUTED; label_color=$C_MUTED; detail_color=$C_MUTED ;;
        *) glyph=$G_SKIP; glyph_color=$C_INFO; label_color=$C_TEXT; detail_color=$C_SOFT ;;
    esac
    printf '  %s%s%s  %s%s%s  %s%s%s %s%s%s  %s%s%s\n' \
        "$glyph_color" "$glyph" "$C_RESET" \
        "$C_INFO" "$tag" "$C_RESET" \
        "$label_color" "$LBL" "$C_RESET" \
        "$C_MUTED" "$LEADER" "$C_RESET" \
        "$detail_color" "$detail" "$C_RESET"
}

ui_plain_or_note() {
    if [ "$USE_UI" -ne 1 ]; then
        printf '%s\n' "$1"
        return
    fi
    case "$1" in
        Note:*) printf '\n  %s%s%s %s%s%s\n' "$C_WARN" "$G_WARN" "$C_RESET" "$C_SOFT" "$1" "$C_RESET" ;;
        *) printf '  %s%s%s\n' "$C_SOFT" "$1" "$C_RESET" ;;
    esac
}

ui_box_row() {
    # $1 plain text (for width), $2 colored text, $3 inner width
    pad=$(ui_repeat ' ' $(($3 - ${#1})))
    printf '  %s%s%s%s%s%s%s%s\n' "$C_G1" "$G_V" "$C_RESET" "$2" "$pad" "$C_G4" "$G_V" "$C_RESET"
}

ui_done_box() {
    ver=$1
    bin_path=$2
    if [ "$USE_UI" -ne 1 ]; then
        printf '\nInstalled Drawplate %s to %s\n' "$ver" "$bin_path"
        printf '%s\n' 'Next:' '  drawplate --help' '  drawplate setup        (shows how to install FFmpeg)'
        return
    fi
    plain1="  o Installed Drawplate $ver"
    plain2="    Path: $bin_path"
    plain3="    Next: drawplate --help  .  drawplate setup"
    inner=58
    for plain in "$plain1" "$plain2" "$plain3"; do
        if [ $((${#plain} + 2)) -gt "$inner" ]; then
            inner=$((${#plain} + 2))
        fi
    done
    printf '\n'
    ui_gradient "<$(ui_repeat - "$inner")>" 0 $((inner + 2)) | sed 's/^/  /'
    ui_box_row '' '' "$inner"
    ui_box_row "$plain1" "  ${C_OK}${G_OK}${C_RESET} ${C_BOLD}${C_TEXT}Installed Drawplate${C_RESET} ${C_ACCENT}${ver}${C_RESET}" "$inner"
    ui_box_row "$plain2" "    ${C_MUTED}Path:${C_RESET} ${C_TEXT}${bin_path}${C_RESET}" "$inner"
    ui_box_row "$plain3" "    ${C_MUTED}Next:${C_RESET} ${C_INFO}drawplate --help${C_RESET}  ${C_MUTED}${G_DOT}${C_RESET}  ${C_INFO}drawplate setup${C_RESET}" "$inner"
    ui_box_row '' '' "$inner"
    ui_gradient "{$(ui_repeat - "$inner")}" 4 $((inner + 2)) | sed 's/^/  /'
}

usage() {
    printf '%s\n' "Usage: install.sh [--version <tag>] [--dir <folder>] [--no-setup] [--yes] [--uninstall] [--from <archive> --sha256 <hash>] [--help]"
}

error() {
    if [ "$USE_ERR_UI" -eq 1 ]; then
        printf '\n  %s%s Error:%s %s\n' "$C_ERR" "$G_ERR" "$C_RESET" "$1" >&2
        printf '  %s%s Hint:%s  %s%s%s\n\n' "$C_INFO" "$G_DOT" "$C_RESET" "$C_SOFT" "$2" "$C_RESET" >&2
    else
        printf 'Error: %s\n' "$1" >&2
        printf 'Hint: %s\n' "$2" >&2
    fi
    exit "$3"
}

cleanup() {
    if [ -n "$CURL_PID" ]; then
        kill "$CURL_PID" 2>/dev/null || true
    fi
    if [ "$USE_UI" -eq 1 ]; then
        printf '%s[?25h' "$ESC"
    fi
    if [ -n "$LOCK_DIR" ]; then
        rm -rf "$LOCK_DIR"
    fi
    if [ -n "$STAGING_DIR" ]; then
        rm -rf "$STAGING_DIR"
    fi
}

sha256_file() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "$1" | awk '{print $1}'
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 "$1" | awk '{print $1}'
    else
        error "No SHA-256 utility is available." "Install sha256sum or shasum." 13
    fi
}

# Live download line: spinner, step, label, gradient comet bar, size, speed.
download_with_ui() {
    src_url=$1
    dest_file=$2
    if [ "$USE_UI" -ne 1 ]; then
        curl -fsSL -o "$dest_file" "$src_url"
        return $?
    fi

    ui_label 'Downloading Drawplate'
    curl -fsSL -o "$dest_file" "$src_url" &
    CURL_PID=$!
    printf '%s[?25l' "$ESC"
    began=$(date +%s)
    tick=0
    while kill -0 "$CURL_PID" 2>/dev/null; do
        cur_bytes=0
        if [ -f "$dest_file" ]; then
            cur_bytes=$(wc -c < "$dest_file" 2>/dev/null | tr -d ' ')
        fi
        now=$(date +%s)
        meter=$(DP_TICK=$tick DP_BYTES=${cur_bytes:-0} DP_ELAPSED=$((now - began)) awk "$AWK_LIB"'
        BEGIN {
            esc = ENVIRON["DP_ESC"]; tick = ENVIRON["DP_TICK"] + 0
            bytes = ENVIRON["DP_BYTES"] + 0; el = ENVIRON["DP_ELAPSED"] + 0
            w = 16; cyc = 2 * (w - 1); k = tick % cyc; p = (k < w) ? k : cyc - k
            out = ""
            for (i = 0; i < w; i++) {
                d = i - p; if (d < 0) d = -d
                if (d <= 4) {
                    f = 1 - d / 5; grad(i / (w - 1))
                    out = out fg(int(30 + (R - 30) * f), int(41 + (G - 41) * f), int(59 + (B - 59) * f)) ENVIRON["G_BAR"]
                } else {
                    out = out fg(51, 65, 85) ENVIRON["G_BAR"]
                }
            }
            mib = bytes / 1048576
            stats = sprintf("%.1f MiB", mib)
            if (el >= 1) stats = stats sprintf("  %.1f MiB/s", mib / el)
            printf "%s%s[0m  %s%s%s[0m", out, esc, fg(148, 163, 184), stats, esc
        }' 2>/dev/null)
        printf '%s  %s%s%s  %s3/8%s  %s%s%s %s%s%s  %s%s\033[K' \
            "$CR" "$C_ACCENT" "$(ui_spinner_frame "$tick")" "$C_RESET" \
            "$C_INFO" "$C_RESET" "$C_TEXT" "$LBL" "$C_RESET" "$C_MUTED" "$LEADER" "$C_RESET" "$meter" ""
        tick=$((tick + 1))
        sleep 0.1
    done
    rc=0
    wait "$CURL_PID" || rc=$?
    CURL_PID=""
    printf '%s%s[K%s[?25h' "$CR" "$ESC" "$ESC"
    return "$rc"
}

progress_complete() {
    file=$1
    started=$2
    show_ui_bar=${3:-1}
    bytes=$(wc -c < "$file" | tr -d ' ')
    finished=$(date +%s)
    elapsed=$((finished - started))
    mib=$(awk -v value="$bytes" 'BEGIN { printf "%.1f", value / 1048576 }')
    if [ "$USE_UI" -ne 1 ]; then
        printf '%s\n' '      25%' '      50%' '      75%'
        printf '      100%%  %s MiB in %ss\n' "$mib" "$elapsed"
        return
    fi
    if [ "$show_ui_bar" -ne 1 ]; then
        return
    fi
    ui_step '[3/8]' 'Downloading Drawplate' '[ok]' "$mib MiB in ${elapsed}s"
}

while [ "$#" -gt 0 ]; do
    case "$1" in
        --version)
            [ "$#" -ge 2 ] || error "Missing value for --version." "Provide a release tag." 10
            VERSION=$2
            shift 2
            ;;
        --dir)
            [ "$#" -ge 2 ] || error "Missing value for --dir." "Provide an install folder." 10
            INSTALL_DIR=$2
            shift 2
            ;;
        --no-setup) NO_SETUP=1; shift ;;
        --yes) YES=1; shift ;;
        --uninstall) UNINSTALL=1; shift ;;
        --from)
            [ "$#" -ge 2 ] || error "Missing value for --from." "Provide an archive path." 10
            FROM_ARCHIVE=$2
            shift 2
            ;;
        --sha256)
            [ "$#" -ge 2 ] || error "Missing value for --sha256." "Provide the archive SHA-256." 10
            FROM_SHA256=$2
            shift 2
            ;;
        --help) usage; exit 0 ;;
        *) error "Unknown option: $1" "Run 'install.sh --help'." 10 ;;
    esac
done

if [ -n "$FROM_ARCHIVE" ] && [ -z "$FROM_SHA256" ]; then
    error "--sha256 is required with --from." "Provide the archive SHA-256 hash." 10
fi

UNAME_M=$(uname -m)
OS_NAME=$(uname -s)
case "$OS_NAME:$UNAME_M" in
    Linux:x86_64) RID=linux-x64 ;;
    Linux:aarch64|Linux:arm64) RID=linux-arm64 ;;
    Darwin:arm64) RID=osx-arm64 ;;
    *) error "Unsupported platform: $OS_NAME $UNAME_M." "Supported: linux-x64, linux-arm64, osx-arm64, win-x64." 11 ;;
esac

BIN_DIR="${INSTALL_DIR:-$HOME/.local/bin}"
DATA_DIR="$HOME/.local/share/drawplate"
BINARY="$BIN_DIR/drawplate"
MANIFEST="$DATA_DIR/install.json"

if [ "$UNINSTALL" = "1" ]; then
    ui_step '[1/4]' 'Locating installation .....' '[ok]' 'done'
    ui_step '[2/4]' 'Removing files ............' '[ok]' 'done'
    rm -f "$BINARY" "$BINARY.old" "$MANIFEST"
    rmdir "$BIN_DIR" 2>/dev/null || true
    rmdir "$DATA_DIR" 2>/dev/null || true
    ui_step '[3/4]' 'Updating PATH .............' '[ok]' 'done'
    ui_step '[4/4]' 'Finishing .................' '[ok]' 'done'
    ui_plain_or_note "Removed Drawplate. FFmpeg was not touched."
    exit 0
fi

if [ -z "$VERSION" ]; then
    LOCATION=$(curl -fsSI "$BASE_URL/latest" | awk 'tolower($1) == "location:" { sub(/\r$/, "", $2); print $2; exit }')
    VERSION=${LOCATION##*/}
fi

[ -n "$VERSION" ] || error "Could not find a release for $REPO." "Check your internet connection, or set DRAWPLATE_VERSION." 12

TAG=$VERSION
PKG_VERSION=${TAG#v}
ui_banner "$PKG_VERSION"

ARCHIVE="drawplate-$TAG-$RID.tar.gz"
URL="$BASE_URL/download/$TAG/$ARCHIVE"

mkdir -p "$DATA_DIR"
LOCK_DIR="$DATA_DIR/.lock"
if ! mkdir "$LOCK_DIR" 2>/dev/null; then
    if command -v stat >/dev/null 2>&1; then
        LOCK_TIME=$(stat -c %Y "$LOCK_DIR" 2>/dev/null || stat -f %m "$LOCK_DIR" 2>/dev/null || echo 0)
    else
        LOCK_TIME=0
    fi
    NOW=$(date +%s)
    LOCK_AGE=$((NOW - LOCK_TIME))
    if [ "$LOCK_AGE" -lt 1800 ]; then
        error "Another installation is running (lock: $LOCK_DIR)." "Wait for it, or delete that folder if no installer is running." 15
    fi
    rm -rf "$LOCK_DIR"
    mkdir "$LOCK_DIR" || error "Could not create lock $LOCK_DIR." "Choose another install location." 5
fi

STAGING_DIR="$BIN_DIR/.drawplate-staging-$$"
trap cleanup EXIT
trap 'cleanup; exit 130' HUP INT TERM

REPAIR=0
if [ -f "$MANIFEST" ] && [ -f "$BINARY" ]; then
    MANIFEST_VERSION=$(sed -n 's/.*"version":"\([^"]*\)".*/\1/p' "$MANIFEST")
    MANIFEST_HASH=$(sed -n 's/.*"binarySha256":"\([^"]*\)".*/\1/p' "$MANIFEST")
    BINARY_HASH=$(sha256_file "$BINARY")
    BINARY_VERSION=$("$BINARY" --version 2>/dev/null || true)
    if [ "$MANIFEST_VERSION" = "$PKG_VERSION" ] && [ "$BINARY_HASH" = "$MANIFEST_HASH" ] && [ "$BINARY_VERSION" = "drawplate $PKG_VERSION" ]; then
        ui_step '[1/8]' 'Detecting platform .....' '[ok]' "$RID"
        ui_step '[2/8]' 'Finding release ........' '[ok]' "$TAG"
        ui_step '[3/8]' 'Downloading Drawplate ....' '[skipped]' 'up to date'
        ui_step '[4/8]' 'Downloading checksums ....' '[skipped]' 'up to date'
        ui_step '[5/8]' 'Verifying checksum .......' '[skipped]' 'up to date'
        ui_step '[6/8]' 'Installing .............' '[skipped]' 'up to date'
        ui_step '[7/8]' 'Checking the install ....' '[skipped]' 'up to date'
        ui_step '[8/8]' 'Finishing ..............' '[ok]' 'done'
        ui_done_box "$PKG_VERSION" "$BINARY"
        case ":$PATH:" in *":$BIN_DIR:"*) ;; *) ui_plain_or_note "Note: $BIN_DIR is not on your PATH." ;; esac
        exit 0
    fi
    REPAIR=1
fi

mkdir -p "$STAGING_DIR" "$BIN_DIR"
ui_step '[1/8]' 'Detecting platform .....' '[ok]' "$RID"
ui_step '[2/8]' 'Finding release ........' '[ok]' "$TAG"
if [ "$USE_UI" -ne 1 ]; then
    ui_step '[3/8]' 'Downloading Drawplate ....' '' ''
fi

DOWNLOAD_START=$(date +%s)
if [ -n "$FROM_ARCHIVE" ]; then
    cp "$FROM_ARCHIVE" "$STAGING_DIR/$ARCHIVE" || error "Download failed: $FROM_ARCHIVE." "Check the offline archive path." 12
else
    download_with_ui "$URL" "$STAGING_DIR/$ARCHIVE" || error "Download failed: $URL." "Retry, or use --from <archive> --sha256 <hash>." 12
fi
progress_complete "$STAGING_DIR/$ARCHIVE" "$DOWNLOAD_START"

ACTUAL_HASH=$(sha256_file "$STAGING_DIR/$ARCHIVE")
if [ -n "$FROM_ARCHIVE" ]; then
    EXPECTED_HASH=$FROM_SHA256
else
    SUMS_URL="$BASE_URL/download/$TAG/SHA256SUMS"
    SUMS_START=$(date +%s)
    curl -fsSL -o "$STAGING_DIR/SHA256SUMS" "$SUMS_URL" || error "Download failed: $SUMS_URL." "Retry." 12
    progress_complete "$STAGING_DIR/SHA256SUMS" "$SUMS_START" 0
    EXPECTED_HASH=$(awk -v name="$ARCHIVE" '{ file = $2; sub(/^\.\//, "", file) } file == name { print $1; exit }' "$STAGING_DIR/SHA256SUMS")
fi

if [ -z "$EXPECTED_HASH" ] || [ "$EXPECTED_HASH" != "$ACTUAL_HASH" ]; then
    error "Checksum mismatch for $ARCHIVE." "Nothing was installed. Retry; if it repeats, report it." 13
fi

ui_step '[4/8]' 'Downloading checksums ....' '[ok]' 'done'
ui_step '[5/8]' 'Verifying checksum .......' '[ok]' 'done'

mkdir -p "$STAGING_DIR/x"
tar -xzf "$STAGING_DIR/$ARCHIVE" -C "$STAGING_DIR/x" || error "Could not install to $BIN_DIR." "The release archive could not be extracted." 14

FILE_COUNT=$(find "$STAGING_DIR/x" -type f | wc -l | tr -d ' ')
if [ "$FILE_COUNT" -ne 3 ] || [ ! -f "$STAGING_DIR/x/drawplate" ] || [ ! -f "$STAGING_DIR/x/LICENSE" ] || [ ! -f "$STAGING_DIR/x/THIRD-PARTY-NOTICES.md" ]; then
    error "Could not install to $BIN_DIR." "The archive contains unexpected files." 14
fi

if [ -f "$BINARY" ]; then
    mv "$BINARY" "$BINARY.old"
fi
chmod +x "$STAGING_DIR/x/drawplate"
mv "$STAGING_DIR/x/drawplate" "$BINARY"

BINARY_VERSION=$("$BINARY" --version 2>/dev/null || true)
if [ "$BINARY_VERSION" != "drawplate $PKG_VERSION" ]; then
    rm -f "$BINARY"
    if [ -f "$BINARY.old" ]; then mv "$BINARY.old" "$BINARY"; fi
    error "The installed program did not start or reported the wrong version. The previous version was restored." "Retry with a verified release archive." 14
fi
rm -f "$BINARY.old"

INSTALLED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)
BINARY_HASH=$(sha256_file "$BINARY")
ARCHIVE_HASH=$(sha256_file "$STAGING_DIR/$ARCHIVE")
MANIFEST_TMP="$MANIFEST.tmp.$$"
printf '{"version":"%s","rid":"%s","archiveSha256":"%s","binarySha256":"%s","installedAt":"%s","path":"%s"}\n' "$PKG_VERSION" "$RID" "$ARCHIVE_HASH" "$BINARY_HASH" "$INSTALLED_AT" "$BINARY" > "$MANIFEST_TMP"
mv -f "$MANIFEST_TMP" "$MANIFEST"

if [ "$REPAIR" -eq 1 ]; then
    ui_step '[6/8]' 'Installing .............' '[ok]' 'repairing'
else
    ui_step '[6/8]' 'Installing .............' '[ok]' 'done'
fi
ui_step '[7/8]' 'Checking the install ....' '[ok]' 'done'
ui_step '[8/8]' 'Finishing ..............' '[ok]' 'done'

ui_done_box "$PKG_VERSION" "$BINARY"
case ":$PATH:" in *":$BIN_DIR:"*) ;; *) ui_plain_or_note "Note: $BIN_DIR is not on your PATH." ;; esac

if ! command -v ffmpeg >/dev/null 2>&1 && [ "$NO_SETUP" = "0" ] && [ "$YES" = "0" ]; then
    ui_plain_or_note 'FFmpeg was not found on this machine.'
    if [ -t 0 ] && [ -t 1 ]; then
        printf "Run 'drawplate setup' now? [Y/n] "
        read -r answer || answer=y
        case "$answer" in n|N) ;; *) "$BINARY" setup || true ;; esac
    fi
elif [ "$YES" = "1" ]; then
    "$BINARY" setup || true
fi

exit 0
